                configuration.merge_with(PartialConfiguration {
                    formatter: Some(formatter_configuration.clone()),
                    javascript: Some(PartialJavascriptConfiguration {
                        formatter: Some(javascript_configuration.clone()),
                        ..Default::default()
                    }),
                    ..Default::default()
                });

